#!/usr/bin/env python3
import contextlib, io, json, os, threading, traceback
from datetime import datetime, timezone
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import urlparse

ROOT = Path('/home/user/workspace/kernel_lab')
STATE = ROOT / 'q4_pipeline.json'
EVENTS = ROOT / 'kernel_events.jsonl'
SERVICE_LOG = ROOT / 'kernel_service.log'
NAMESPACE = {'__name__': '__q4_pipeline__'}
LOCK = threading.Lock()

class Handler(BaseHTTPRequestHandler):
    server_version = 'Q4PipelineNotebook/1.0'
    def send_json(self, status, obj):
        raw = json.dumps(obj, ensure_ascii=False, indent=2).encode('utf-8')
        self.send_response(status)
        self.send_header('Content-Type', 'application/json; charset=utf-8')
        self.send_header('Content-Length', str(len(raw)))
        self.end_headers(); self.wfile.write(raw)
    def do_GET(self):
        path = urlparse(self.path).path
        if path == '/':
            html = """<!doctype html><meta charset='utf-8'><title>Q4 Pipeline Notebook</title><h1>Q4 Pipeline Notebook</h1><p>Persistent Python kernel. Use the Execute API to run ordered cells.</p><pre id='cells'></pre><script>fetch('/state').then(r=>r.json()).then(x=>document.querySelector('#cells').textContent=JSON.stringify(x,null,2));</script>""".encode()
            self.send_response(200); self.send_header('Content-Type','text/html; charset=utf-8'); self.send_header('Content-Length',str(len(html))); self.end_headers(); self.wfile.write(html); return
        if path == '/state':
            if STATE.exists():
                self.send_json(200, json.loads(STATE.read_text(encoding='utf-8')))
            else:
                self.send_json(200, {'format':'bc11-pipeline/v1','cells':[]})
            return
        if path == '/health':
            self.send_json(200, {'status':'ok','kernel':'persistent'}); return
        self.send_json(404, {'error':'not_found'})
    def do_POST(self):
        if urlparse(self.path).path != '/execute':
            self.send_json(404, {'error':'not_found'}); return
        try:
            length = int(self.headers.get('Content-Length','0'))
            request = json.loads(self.rfile.read(length).decode('utf-8'))
        except Exception:
            self.send_json(400, {'error':'invalid_request'}); return
        cells = request.get('cells') if isinstance(request,dict) else None
        if not isinstance(cells,list) or not cells:
            self.send_json(400, {'error':'invalid_request'}); return
        section = request.get('section','A')
        saved_cells=[]; executed=[]
        with LOCK:
            for idx, cell in enumerate(cells,1):
                if not isinstance(cell,dict):
                    self.send_json(400, {'error':'invalid_request'}); return
                title = cell.get('title') or cell.get('name') or cell.get('label') or f'Cell {idx}'
                code = cell.get('code') or cell.get('source')
                if not isinstance(title,str) or not isinstance(code,str) or not code.strip():
                    self.send_json(400, {'error':'invalid_request'}); return
                output = io.StringIO(); error=None
                try:
                    with contextlib.redirect_stdout(output):
                        exec(compile(code, f'<Section {section} cell {idx}>','exec'),NAMESPACE,NAMESPACE)
                except Exception:
                    error=traceback.format_exc()
                    output.write(error)
                output_text=output.getvalue().rstrip('\n')
                row={'section':section,'execution_count':idx,'title':title,'code':code,'output':output_text,'outputs':[output_text] if output_text else [],'status':'error' if error else 'ok'}
                saved_cells.append(row)
                event={'timestamp':datetime.now(timezone.utc).isoformat(),'event':'cell_executed','type':'cell_executed','section':section,'execution_count':idx,'title':title,'cell':title,'code':code,'output':output_text,'status':row['status']}
                with EVENTS.open('a',encoding='utf-8') as f: f.write(json.dumps(event,ensure_ascii=False)+'\n')
                executed.append({'title':title,'output':output_text,'status':row['status']})
                if error: break
            state={'format':'bc11-pipeline/v1','section':section,'cells':saved_cells}
            tmp=STATE.with_suffix('.json.tmp')
            tmp.write_text(json.dumps(state,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
            tmp.replace(STATE)
        self.send_json(200, {'section':section,'cells':executed})
    def log_message(self, fmt, *args):
        with SERVICE_LOG.open('a',encoding='utf-8') as f: f.write('%s - %s\n' % (self.log_date_time_string(),fmt%args))

if __name__ == '__main__':
    server=ThreadingHTTPServer(('127.0.0.1',18111),Handler)
    server.daemon_threads=True
    server.serve_forever()
PY
